#[no_mangle]
pub unsafe extern "C" fn operators(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<5{return -1}let op=*v;let ra=*v.add(1);let ca=*v.add(2);if(op!=0&&op!=1)||!(1..=16).contains(&ra)||!(0..=16).contains(&ca)||ra*ca>256{return -1}let count=(ra*ca)as usize;let pb=3+count;if n<pb+2{return -1}let rb=*v.add(pb);let cb=*v.add(pb+1);if !(1..=16).contains(&rb)||!(0..=16).contains(&cb)||rb*cb>256||n!=pb+2+(rb*cb)as usize{return -1}let vals=std::slice::from_raw_parts(v,n);if vals[3..pb].iter().chain(vals[pb+2..].iter()).any(|x|!(-1_000_000..=1_000_000).contains(x)){return -1}if ra!=rb||ca!=cb{return -1}let bytes=count*4;if cap<bytes||(bytes>0&&out.is_null()){return -2}for i in 0..count{let x=if op==0{vals[3+i]+vals[pb+2+i]}else{vals[3+i]-vals[pb+2+i]};let b=(x as i32).to_le_bytes();for k in 0..4{*out.add(i*4+k)=b[k];}}count as i64}
